import java.util.concurrent.atomic.AtomicBoolean;

public final class MainActivity extends Activity {
    static final int PAPER=0xfff7f4ed, INK=0xff253d34, GREEN=0xff28594c, MUTED=0xff59655e;
    ProjectStore store;MediaLibrary media;DesignRenderer renderer;Project project;
    History history=new History();EditorCanvas preview;LinearLayout root,inspector;TextView status,warnings;Button undo,redo;
    String selected="headline",panel="Words",importTarget="photo",pendingMime;int photoSlot;
    File pendingExport;boolean busy;AtomicBoolean cancelMotion=new AtomicBoolean();
    final Handler handler=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();
    final Runnable autoSave=()->save(false);
    final Runnable refreshWarnings=()->{if(project!=null&&warnings!=null){List<String>w=renderer.warnings(project);warnings.setText(w.isEmpty()?"Ready to post · all text fits":String.join("\n",w));warnings.setTextColor(w.isEmpty()?GREEN:0xff843c26);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);store=new ProjectStore(this);media=new MediaLibrary(this,store);renderer=new DesignRenderer(this,media);
        if(state!=null){selected=state.getString("selected","headline");panel=state.getString("panel","Words");importTarget=state.getString("importTarget","photo");photoSlot=state.getInt("slot");String path=state.getString("export");if(path!=null)pendingExport=new File(getCacheDir(),path);pendingMime=state.getString("mime");}
        String id=getPreferences(0).getString("active",null);if(id!=null)try{project=store.load(id);}catch(IOException e){message(e.getMessage());}
        if(project==null)home();else editor();
        if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(0,this::back);
    }
    @Override public void onBackPressed(){back();}
    void back(){if(busy){message("Finish or cancel the export first.");return;}if(project!=null){if(save(false)){project=null;getPreferences(0).edit().remove("active").apply();home();}}else finish();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);save(false);state.putString("selected",selected);state.putString("panel",panel);state.putString("importTarget",importTarget);state.putInt("slot",photoSlot);if(pendingExport!=null)state.putString("export",pendingExport.getName());state.putString("mime",pendingMime);}
    @Override protected void onStop(){save(false);super.onStop();}
    @Override protected void onDestroy(){cancelMotion.set(true);handler.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
    int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(5),0,dp(5));return v;}
    TextView title(String s,int size){TextView v=text(s,size,INK);v.setTypeface(Typeface.create("sans-serif",1));return v;}
    LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}
    LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    GradientDrawable surface(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(14));return d;}
    Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setAllCaps(false);b.setMinHeight(dp(48));b.setTextColor(GREEN);b.setOnClickListener(v->{if(!busy)action.run();});return b;}
    void equal(LinearLayout row,View child){row.addView(child,new LinearLayout.LayoutParams(0,-2,1));}
    void base(){root=column();root.setPadding(dp(20),dp(12),dp(20),dp(20));root.setBackgroundColor(PAPER);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(root);scroll.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){Insets i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(i.left,i.top,i.right,i.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(scroll);}
    void home(){preview=null;status=null;warnings=null;undo=null;redo=null;inspector=null;base();root.addView(text("K R E A T I V   P O S T",12,GREEN));root.addView(title("Made here.\nShared everywhere.",34));root.addView(text("Your photo, your words, your brand — ready to post.",16,MUTED));root.addView(title("Start with a little inspiration",21));root.addView(text("Five original layouts for your café or bakery",14,MUTED));
        for(int i=0;i<Templates.NAMES.length;i++){final int index=i;LinearLayout card=column();card.setBackground(surface(Color.WHITE));card.setPadding(dp(14),dp(14),dp(14),dp(10));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(12);root.addView(card,cp);EditorCanvas sample=new EditorCanvas(this,renderer,Templates.create(i));sample.editable=false;sample.setContentDescription(Templates.NAMES[i]+" template preview");int width=Math.min(dp(280),getResources().getDisplayMetrics().widthPixels-dp(68));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(width,width);pp.gravity=Gravity.CENTER;card.addView(sample,pp);card.addView(title(Templates.NAMES[i],20));card.addView(text(Templates.USES[i],14,MUTED));card.addView(button("Use "+Templates.NAMES[i],()->{project=Templates.create(index);try{Brand b=Brand.load(this);if(b!=null)b.apply(project);}catch(IOException e){message(e.getMessage());}history=new History();selected="headline";panel="Words";if(save(false))editor();}));}
        root.addView(title("Your saved projects",23));List<File> files=store.files();if(files.isEmpty())root.addView(text("Your first promotion starts above. It will be saved on this device.",15,MUTED));for(File file:files){String id=file.getName().replace(".json","");try{Project saved=store.load(id);root.addView(button(saved.name+" · "+(saved.story?"Story":"Square"),()->{try{project=store.load(id);history=new History();save(false);editor();}catch(IOException e){message(e.getMessage());}}));root.addView(button("Duplicate "+saved.name,()->duplicate(saved)));}catch(IOException e){root.addView(text("Unreadable project: "+file.getName()+". Original file retained.",14,0xff843c26));}}
        root.addView(button("Privacy, licences & export limits",this::about));root.addView(text("No account. No ads. No watermarks.",14,MUTED));}
    void editor(){base();LinearLayout header=row();header.addView(button("‹ Projects",this::back));equal(header,title("Kreativ Post",21));root.addView(header);root.addView(button(project.name+" · Rename",this::rename));status=text("Saved on this device",13,MUTED);root.addView(status);
        LinearLayout actions=row();undo=button("Undo",()->{project=history.undo(project);save(false);editor();});redo=button("Redo",()->{project=history.redo(project);save(false);editor();});equal(actions,undo);equal(actions,redo);equal(actions,button("Save",()->save(true)));root.addView(actions);updateHistory();
        LinearLayout formats=row();equal(formats,button((!project.story?"✓ ":"")+"Square",()->format(false)));equal(formats,button((project.story?"✓ ":"")+"Story",()->format(true)));root.addView(formats);
        preview=new EditorCanvas(this,renderer,project);preview.selected=selected;preview.listener=new EditorCanvas.Listener(){public void select(String key){selected=key;panel="Layout";showInspector();}public void beforeChange(){history.record(project);}public void changed(){change();showInspector();}};
        LinearLayout scene=column();scene.setGravity(Gravity.CENTER);scene.setPadding(0,dp(8),0,dp(8));int width=Math.min(dp(project.story?240:440),getResources().getDisplayMetrics().widthPixels-dp(40));scene.addView(preview,new LinearLayout.LayoutParams(width,-2));root.addView(scene);root.addView(text("Drag to move · bottom-right handle to resize\nGuides snap to margins and centres. Use Layout controls without gestures.",12,MUTED));warnings=text("",13,GREEN);root.addView(warnings);refreshWarnings.run();
        // Two rows keep tab touch targets readable at large system font sizes.
        LinearLayout tabs=row();equal(tabs,button("Words",()->tab("Words")));equal(tabs,button("Layout",()->tab("Layout")));root.addView(tabs);LinearLayout more=row();equal(more,button("Photos",()->tab("Photos")));equal(more,button("Brand",()->tab("Brand")));root.addView(more);
        inspector=column();inspector.setBackground(surface(Color.WHITE));inspector.setPadding(dp(14),dp(10),dp(14),dp(14));root.addView(inspector);showInspector();root.addView(title("Ready to share",21));root.addView(text((project.story?"1080 × 1920":"1080 × 1080")+" · watermark-free",14,MUTED));LinearLayout exports=row();Button png=button("Export PNG",()->prepareExport(false));png.setTextColor(Color.WHITE);png.setBackground(surface(GREEN));equal(exports,png);equal(exports,button("Export JPEG",()->prepareExport(true)));root.addView(exports);root.addView(button("Duplicate this project",()->duplicate(project)));addMotionEntry();root.addView(button("Privacy, licences & export limits",this::about));}
    void tab(String name){panel=name;showInspector();}
    void format(boolean story){if(story==project.story)return;history.record(project);project.story=story;save(false);editor();}
    void duplicate(Project p){try{project=store.duplicate(p);history=new History();save(false);editor();}catch(IOException e){message(e.getMessage());}}
    void updateHistory(){if(undo!=null){undo.setEnabled(history.canUndo());redo.setEnabled(history.canRedo());}}
    void change(){if(preview!=null){preview.project=project;preview.invalidate();}updateHistory();if(status!=null)status.setText("Saving…");handler.removeCallbacks(autoSave);handler.postDelayed(autoSave,450);handler.removeCallbacks(refreshWarnings);handler.postDelayed(refreshWarnings,120);}
    boolean save(boolean notify){handler.removeCallbacks(autoSave);if(project==null)return true;try{store.save(project);getPreferences(0).edit().putString("active",project.id).apply();if(status!=null)status.setText("Saved on this device");if(notify)message("Project saved. Reopen it from Projects tomorrow.");return true;}catch(IOException e){if(status!=null)status.setText("Not saved — retry Save");message("Save failed: "+e.getMessage());return false;}}
    interface TextSetter{void set(String v);}
    EditText field(LinearLayout parent,String label,String value,int max,TextSetter setter){parent.addView(text(label,14,INK));EditText f=new EditText(this);f.setHint(label);f.setContentDescription(label);f.setTextColor(INK);f.setTextSize(16);f.setMinHeight(dp(48));f.setInputType(1|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);f.setFilters(new InputFilter[]{new InputFilter.LengthFilter(max)});f.setText(value);parent.addView(f);if(setter!=null)f.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){history.record(project);setter.set(s.toString());change();}});return f;}
    void showInspector(){if(inspector==null)return;inspector.removeAllViews();inspector.addView(title(panel,19));switch(panel){case "Words":field(inspector,"Headline",project.headline,600,v->project.headline=v);field(inspector,"Description",project.description,1000,v->project.description=v);field(inspector,"Price / offer",project.price,120,v->project.price=v);field(inspector,"Business name",project.business,200,v->project.business=v);field(inspector,"Business footer / hours",project.hours,300,v->project.hours=v);break;case "Photos":photos();break;case "Brand":brand();break;default:layoutControls();}}
    void photos(){inspector.addView(text("JPEG, PNG or WebP · up to 40 MB each\nOriginals stay unchanged. Static posts use photo 1; the motion prototype uses all three.",14,MUTED));for(int i=0;i<3;i++){final int slot=i;if(i<=project.photos.size())inspector.addView(button((i<project.photos.size()?"Replace":"Add")+" photo "+(i+1),()->importImage("photo",slot)));if(i<project.photos.size())inspector.addView(button("Remove photo "+(i+1),()->{history.record(project);project.photos.remove(slot);change();showInspector();}));}cropControls(project.layout().get("photo"));inspector.addView(button("Import / replace logo",()->importImage("logo",0)));if(!project.logo.isEmpty())inspector.addView(button("Remove logo",()->{history.record(project);project.logo="";change();showInspector();}));}
    void brand(){inspector.addView(text("One saved brand on this device. Save once, apply to future promotions.",14,MUTED));field(inspector,"Business name",project.business,200,v->project.business=v);field(inspector,"Footer / opening hours",project.hours,300,v->project.hours=v);fontControl();for(String target:new String[]{"background","ink","accent"})inspector.addView(button(target.equals("ink")?"Text colour":target+" colour",()->colour(target)));inspector.addView(button("Import / replace brand logo",()->importImage("logo",0)));inspector.addView(button("Save this brand",()->{try{Brand.from(project).save(this);message("Brand saved. New promotions will use these details.");}catch(IOException e){message("Could not save brand: "+e.getMessage());}}));inspector.addView(button("Apply saved brand",()->{try{Brand b=Brand.load(this);if(b==null){message("Save a brand first.");return;}history.record(project);b.apply(project);change();showInspector();}catch(IOException e){message(e.getMessage());}}));}
    void fontControl(){inspector.addView(text("Headline font",14,INK));LinearLayout r=row();for(String f:new String[]{"lora","dmsans"})equal(r,button((project.font.equals(f)?"✓ ":"")+(f.equals("lora")?"Lora":"DM Sans"),()->{history.record(project);project.font=f;change();showInspector();}));inspector.addView(r);}
    void layoutControls(){inspector.addView(text("Selected element",14,INK));Spinner spinner=new Spinner(this);spinner.setMinimumHeight(dp(48));spinner.setContentDescription("Selected element");spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,Project.ELEMENTS));spinner.setSelection(Arrays.asList(Project.ELEMENTS).indexOf(selected));spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> a,View v,int pos,long id){if(!Project.ELEMENTS[pos].equals(selected)){selected=Project.ELEMENTS[pos];preview.selected=selected;preview.invalidate();showInspector();}}public void onNothingSelected(AdapterView<?> a){}});inspector.addView(spinner);Project.Element e=project.layout().get(selected);
        slider("Left position",e.x,0,1,v->e.x=Geometry.clamp(v,0,1-e.w));slider("Top position",e.y,0,1,v->e.y=Geometry.clamp(v,0,1-e.h));slider("Width",e.w,.05f,1,v->{e.w=v;e.x=Math.min(e.x,1-v);});slider("Height",e.h,.03f,1,v->{e.h=v;e.y=Math.min(e.y,1-v);});
        if(selected.equals("photo"))cropControls(e);else if(!selected.equals("logo")){fontControl();slider("Text size",e.size,.016f,.22f,v->e.size=v);slider("Letter spacing",e.tracking,-.03f,.12f,v->e.tracking=v);slider("Line spacing",e.leading,1,1.8f,v->e.leading=v);LinearLayout align=row();for(int i=0;i<3;i++){final int n=i;equal(align,button(new String[]{"Left","Centre","Right"}[i],()->{history.record(project);e.alignment=n;change();}));}inspector.addView(align);inspector.addView(button("Element text colour",()->colour("element")));}inspector.addView(button("Centre element horizontally",()->{history.record(project);e.x=(1-e.w)/2;change();showInspector();}));preview.selected=selected;preview.invalidate();}
    void cropControls(Project.Element e){inspector.addView(title("Photo crop & positioning",16));slider("Photo zoom",e.zoom,1,3,v->e.zoom=v);slider("Photo horizontal crop",e.panX,0,1,v->e.panX=v);slider("Photo vertical crop",e.panY,0,1,v->e.panY=v);}
    interface FloatSetter{void set(float v);}
    void slider(String label,float current,float min,float max,FloatSetter setter){TextView caption=text(label+" · "+String.format(Locale.ROOT,"%.2f",current),13,INK);inspector.addView(caption);SeekBar s=new SeekBar(this);s.setContentDescription(label);s.setMax(1000);s.setProgress(Math.round((current-min)/(max-min)*1000));s.setMinimumHeight(dp(48));inspector.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){boolean tracking;public void onStartTrackingTouch(SeekBar b){tracking=true;history.record(project);}public void onStopTrackingTouch(SeekBar b){tracking=false;save(false);}public void onProgressChanged(SeekBar b,int value,boolean user){if(!user)return;if(!tracking)history.record(project);float v=min+(max-min)*value/1000f;setter.set(v);caption.setText(label+" · "+String.format(Locale.ROOT,"%.2f",v));change();}});}
    void colour(String target){LinearLayout box=column();box.setPadding(dp(20),dp(10),dp(20),0);int c=target.equals("background")?project.background:target.equals("accent")?project.accent:target.equals("element")?project.layout().get(selected).color:project.ink;if(c==0)c=project.ink;EditText hex=field(box,"Hex colour (#RRGGBB)",String.format("#%06X",c&0xffffff),7,null);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Choose colour").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Apply",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{String value=hex.getText().toString().trim();if(!value.matches("#[0-9a-fA-F]{6}")){hex.setError("Enter # and six hexadecimal digits");return;}history.record(project);int color=Color.parseColor(value);switch(target){case "background":project.background=color;break;case "accent":project.accent=color;break;case "element":project.layout().get(selected).color=color;break;default:project.ink=color;}change();dialog.dismiss();}));dialog.show();}
    void rename(){LinearLayout box=column();box.setPadding(dp(20),0,dp(20),0);EditText f=field(box,"Project name",project.name,100,null);new AlertDialog.Builder(this).setTitle("Name this promotion").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{history.record(project);project.name=f.getText().toString().trim();if(project.name.isEmpty())project.name="Untitled promotion";save(false);editor();}).show();}
    void importImage(String target,int slot){save(false);importTarget=target;photoSlot=slot;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/jpeg","image/png","image/webp"});try{startActivityForResult(i,101);}catch(ActivityNotFoundException e){message("No file picker is available.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){if(request==101)message("Import cancelled. Your project is unchanged.");if(request==102){cleanPending();message("Export cancelled. Your project is saved.");}return;}Uri uri=data.getData();
        if(request==101&&project!=null){String target=importTarget;int slot=photoSlot;setBusy(true,"Importing image…");worker.execute(()->{try{String name=media.importUri(uri);runOnUiThread(()->{if(isDestroyed())return;history.record(project);if(target.equals("logo"))project.logo=name;else if(slot<project.photos.size())project.photos.set(slot,name);else if(project.photos.size()<3)project.photos.add(name);setBusy(false,"");change();showInspector();});}catch(IOException e){runOnUiThread(()->{setBusy(false,"");message(e.getMessage());});}});}
        if(request==102){if(pendingExport==null||!pendingExport.exists()){message("Export was interrupted. Tap Export again.");return;}File file=pendingExport;setBusy(true,"Saving export…");worker.execute(()->{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Destination is not writable");byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Export interrupted");out.write(bytes,0,n);}out.flush();runOnUiThread(()->{cleanPending();setBusy(false,"Export saved");message("Export saved to your chosen location.");});}catch(IOException|RuntimeException e){try{DocumentsContract.deleteDocument(getContentResolver(),uri);}catch(Exception ignored){}runOnUiThread(()->{cleanPending();setBusy(false,"Export failed");message("Could not save export. Try another folder with free space. "+e.getMessage());});}});}}
    void prepareExport(boolean jpeg){if(!save(false))return;if(!media.missing(project).isEmpty()){message(String.join("\n",media.missing(project)));return;}Project snapshot=project.copy();setBusy(true,"Rendering export…");worker.execute(()->{File file=new File(getCacheDir(),"export-"+UUID.randomUUID()+(jpeg?".jpg":".png"));try(OutputStream out=new FileOutputStream(file)){StaticExport.write(renderer,snapshot,jpeg,out);runOnUiThread(()->{if(isDestroyed()){file.delete();return;}pendingExport=file;pendingMime=jpeg?"image/jpeg":"image/png";setBusy(false,"");chooseExport(snapshot.name,jpeg?"jpg":"png");});}catch(IOException|RuntimeException|OutOfMemoryError e){file.delete();runOnUiThread(()->{setBusy(false,"Export failed");message("Export failed. Close other apps, free storage, or try PNG. "+e.getMessage());});}});}
    void chooseExport(String name,String ext){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(pendingMime).putExtra(Intent.EXTRA_TITLE,name.replaceAll("[^\\p{L}\\p{N} ._-]","_")+"."+ext);try{startActivityForResult(i,102);}catch(ActivityNotFoundException e){cleanPending();message("No save-location picker is available.");}}
    void cleanPending(){if(pendingExport!=null)pendingExport.delete();pendingExport=null;pendingMime=null;}
    void setBusy(boolean b,String s){if(isDestroyed())return;busy=b;enableTree(root,!b);if(preview!=null)preview.editable=!b;if(status!=null&&!s.isEmpty())status.setText(s);if(!b)updateHistory();}
    void enableTree(View v,boolean enabled){if(v==null)return;v.setEnabled(enabled);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)enableTree(g.getChildAt(i),enabled);}}
    void message(String s){if(!isDestroyed())Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    void about(){String licences="";try{for(String name:new String[]{"SOURCES.txt","lora-OFL.txt","dmsans-OFL.txt"})try(InputStream in=getAssets().open("licenses/"+name)){licences+="\n\n"+new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}}catch(IOException e){licences="Licence files are in assets/licenses.";}
        ScrollView scroll=new ScrollView(this);TextView t=text("Your work stays on this device. No account, network permission, ads, analytics, billing or hidden uploads. File pickers grant access only to selected files. Uninstalling deletes local projects and imported copies. Export images to keep a shareable copy.\n\nInput: JPEG, PNG and WebP under 40 MB. Images are orientation-corrected, decoded to at most 2048 pixels / 4 MP, and converted to sRGB. Animated input is treated as a still. Output: opaque sRGB PNG / JPEG, 1080 square or 1080×1920 story. Preview and export share one renderer; selection outlines and guides are editor-only.\n\nMotion: experimental silent H.264 MP4, 480×854 at 24 fps for 15 seconds, up to three photos in one template. Physical-device support is not certified. No 1080p promise.\n\nPro is planned separately from editing. €7.99 lifetime is a pricing hypothesis. No purchases are enabled."+licences,14,INK);t.setPadding(dp(20),dp(10),dp(20),dp(20));scroll.addView(t);new AlertDialog.Builder(this).setTitle("Privacy & licences").setView(scroll).setPositiveButton("Done",null).show();}
    void addMotionEntry(){}
}
